{
  "packet_id": "H6-T03-2",
  "claim_id": "C045",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C045.component",
    "value": "The 14-of-90 attachment finding must not be extrapolated into an organization-wide approval-failure rate without evidence about sampling and the remaining records.",
    "scope": "A restriction on population extrapolation and on treating attachment gaps as approval failures; the stated additional evidence is not declared sufficient by itself.",
    "provenance": {
      "refs": [
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the sampled finding, prohibited extrapolation and required evidence condition."
    }
  },
  "signal_basis": {
    "component_id": "C045.signal_basis",
    "value": "The finding concerns missing attachments in 14 of 90 sampled orders. An attachment gap does not establish absent approval, and extrapolation requires evidence about sampling and the remaining records.",
    "scope": "The attachment finding alone, without assuming additional evidence establishing approval failures or supporting population extrapolation.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "Together these spans establish what the finding measures and the evidential limitation on extrapolation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C045.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is a supported restriction, not a conditional warrant awaiting an empirical relation."
    }
  },
  "rationale": "Missing attachments measure a documentation gap, which does not itself establish approval failure. A sampled attachment frequency also cannot establish an organization-wide approval-failure rate without evidence supporting both the classification of failures and population extrapolation. The claim correctly limits that inference without declaring the additional evidence sufficient.",
  "uncertainty": "The actual approval-failure rate remains undetermined; that uncertainty does not undermine the stated restriction.",
  "anomalies": []
}
